if (reb.targets) {
  const u = reb.unfilled_buckets || {};
  const totalUnfilled = Object.entries(u).filter(([k]) => k !== 'buffer').reduce((s, [_, v]) => s + (v > 0 ? v : 0), 0);
  if (totalUnfilled > 0) notes.push(`Cadence short by ${totalUnfilled} (some platform/length buckets unfilled).`);
  if (reb.targets.floor && reb.final_ideas != null && reb.final_ideas < reb.targets.floor) {
    notes.push(`Below floor of ${reb.targets.floor} — only ${reb.final_ideas} valid ideas. Cadence under-covered.`);
  }
  // Aggregate rebalancer flags rather than listing each one
  const flagCount = (reb.flags || []).length;
  if (flagCount > 0) {
    const trimmed = (reb.flags || []).filter(f => /Trimmed|overflow/i.test(f)).length;
    const forced = (reb.flags || []).filter(f => /forced|relaxed/i.test(f)).length;
    if (trimmed > 0) notes.push(`Trimmed ${trimmed} idea(s) to hit cadence target.`);
    if (forced > 0) notes.push(`${forced} idea(s) placed past the soft diversity cap.`);
  }
}

if (typeof p1.substance_pieces === 'number' && typeof reb.final_ideas === 'number' && reb.final_ideas < p1.substance_pieces) {
  // already implied if cadence short — skip unless we want explicit "dropped"
}

if (diag.scrubber && diag.scrubber.total > 0) {
  const pct = diag.scrubber.rewritten / diag.scrubber.total;
  if (pct >= 0.5) notes.push(`Anti-AI Scrubber rewrote hooks on ${diag.scrubber.rewritten}/${diag.scrubber.total} ideas — generator drifted.`);
}

const notesBlock = notes.length
  ? '*Notes:*\n' + notes.map(n => `• ${n}`).join('\n')
  : '_All clean._';

const message = `:brain: *New Idea Batch Ready for Review!* <!channel>\n\n*Client:* ${ctx.client_name}\n*Batch:* ${ctx.batch_name}\n*Source:* Call Transcript - ${ctx.call_title}\n*Total Ideas:* ${rows.length}${prevWeekNote}\n\n${flow}\n\n*Top Ideas:*\n${topIdeas}\n\n${notesBlock}\n\n<${ctx.batch_page_url}|View Batch in Notion>`;

staticData.diagnostics = {};
return [{ json: { slack_message: message, batch_page_url: ctx.batch_page_url, batch_name: ctx.batch_name, client_name: ctx.client_name, total_ideas: rows.length } }];

const schema = $('Get Call Agendas Schema').first().json;
const summaryData = $input.first().json;
const prepData = $('Prepare Transcript for Doc').first().json;
const dbId = $('Extract Client DB IDs').first().json.call_agendas_db_id;

const schemaProps = schema.properties || {};

const titlePropName = Object.entries(schemaProps).find(([, v]) => v.type === 'title')?.[0] || 'Name';
const datePropName = Object.entries(schemaProps).find(([, v]) => v.type === 'date')?.[0];
const transcriptUrlPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'url' && k.toLowerCase().includes('transcript'))?.[0]
  || Object.entries(schemaProps).find(([, v]) => v.type === 'url')?.[0];
const recordingUrlPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'url' && k.toLowerCase().includes('recording'))?.[0];
const summaryPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'rich_text' && k.toLowerCase().includes('summary'))?.[0];
const topicsPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'rich_text' && k.toLowerCase().includes('topic'))?.[0];
const grainIdPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'rich_text' && k.toLowerCase() === 'grain id')?.[0]
  || Object.entries(schemaProps).find(([k, v]) => v.type === 'rich_text' && k.toLowerCase().includes('grain'))?.[0]
  || 'Grain ID';

// Use full client_name for general references, but strip the trailing parenthetical
// (e.g. " (Trial)") when composing the row title so it matches the Beta sync convention:
// "Call N - Client x Digital Leverage" — never "Call N - Client (Trial) x Digital Leverage".
const clientName = prepData.client_name
  || summaryData.client_name
  || $('Pre-process Inputs').first().json?.client_name
  || '?';
const cleanClientName = clientName.replace(/\s*\(.*\)\s*$/, '').trim();

const callNum = prepData.new_call_number || summaryData.new_call_number || '?';

const rawCallDate = prepData.latest_grain_call_date || summaryData.latest_grain_call_date || '';
const callDate = rawCallDate ? rawCallDate.split('T')[0] : '';
if (!callDate) console.log('WARNING: no call date — Call Date will be blank.');

const docUrl = prepData.doc_url || summaryData.doc_url;
const grainCallId = prepData.latest_grain_call_id || summaryData.latest_grain_call_id || '';
const recordingUrl = grainCallId ? `https://grain.com/share/recording/${grainCallId}` : null;
const callSummary = summaryData.call_summary || '';
const callTopics = summaryData.call_topics || '';

const rowTitle = 'Call ' + callNum + ' - ' + cleanClientName + ' x Digital Leverage';
console.log(`Building Call Agendas row: title="${rowTitle}", date="${callDate}", grain_call_id="${grainCallId}"`);

const properties = {};
properties[titlePropName] = { title: [{ type: 'text', text: { content: rowTitle } }] };
if (datePropName && callDate) properties[datePropName] = { date: { start: callDate } };
if (transcriptUrlPropName && docUrl) properties[transcriptUrlPropName] = { url: docUrl };
if (recordingUrlPropName && recordingUrl) properties[recordingUrlPropName] = { url: recordingUrl };
if (summaryPropName && callSummary) properties[summaryPropName] = { rich_text: [{ type: 'text', text: { content: callSummary.substring(0, 2000) } }] };
if (topicsPropName && callTopics) properties[topicsPropName] = { rich_text: [{ type: 'text', text: { content: callTopics.substring(0, 2000) } }] };
if (grainIdPropName && grainCallId) properties[grainIdPropName] = { rich_text: [{ type: 'text', text: { content: grainCallId } }] };

return [{ json: { row_body: { parent: { database_id: dbId }, properties } } }];

// Debug: log what we're about to send to Notion for Create Idea Row
const item = $input.first().json;
const body = {
  parent: { database_id: item.post_lineup_db_id },
  properties: {
    Idea: { title: [{ text: { content: (item.idea || '').substring(0, 200) } }] },
    'Review Status': { select: { name: 'For Review' } },
    Platform: { select: { name: item.platform || 'LinkedIn' } },
    Format: { rich_text: [{ text: { content: (item.format || '').substring(0, 200) } }] },
    'Content Pillar': { rich_text: [{ text: { content: (item.content_pillar || '').substring(0, 200) } }] },
    Topic: { rich_text: [{ text: { content: (item.topic || '').substring(0, 200) } }] },
    Sources: { rich_text: [{ text: { content: (item.sources || '').substring(0, 200) } }] },
    Notes: { rich_text: [{ text: { content: (item.notes_for_reviewer || '').substring(0, 200) } }] }
  }
};
console.log('post_lineup_db_id:', item.post_lineup_db_id);
console.log('Notion body (first 500 chars):', JSON.stringify(body).substring(0, 500));
return [{ json: { ...item, _debug_body: JSON.stringify(body) } }];

parameters.jsonBody:
={{ JSON.stringify({
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 800,
  system: 'You extract structured information from call transcripts. Return ONLY valid JSON with no markdown or extra text.',
  messages: [{
    role: 'user',
    content: 'Analyze this call transcript and return a JSON object with exactly these two fields:

{
  "summary": "3-5 sentence summary of what was discussed on the call",
  "topics": ["Topic one", "Topic two", "Topic three", "Topic four", "Topic five"]
}

Return 5-7 topics as concise bullet-style items (3-7 words each). Focus on the main themes discussed.

Transcript:
' + ($('Prepare Transcript for Doc').first().json.transcript_text || 'No transcript available.').substring(0, 28000)
  }]
}) }}

parameters.jsCode:
const claudeResponse = $input.first().json;
const content = claudeResponse.content?.[0]?.text || '';

let summary = '';
let topics = '';
try {
  const match = content.match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(match ? match[0] : content);
  summary = parsed.summary || '';
  const topicsArray = Array.isArray(parsed.topics) ? parsed.topics : [];
  topics = topicsArray.map(t => `• ${t}`).join('\n');
} catch(e) {
  console.log('Warning: Could not parse summary/topics response:', content.substring(0, 200));
}

// Carry through all prepData fields so downstream can access them
const prepData = $('Prepare Transcript for Doc').first().json;

return [{
  json: {
    ...prepData,
    call_summary: summary,
    call_topics: topics
  }
}];

const clientName = $json.client_name || '(unknown client)';
const reason = $json.abort_reason || '(no reason provided)';
const message = ':warning: *Call Transcript to Ideas failed for ' + clientName + '*

*Reason:* ' + reason + '

No transcript was saved and no batch was created. Fix the issue above and re-run.';
return [{ json: { slack_message: message } }];

const pages = $input.all();
const allRecordings = [];
for (const item of pages) {
  const recs = item.json?.recordings || [];
  for (const r of recs) {
    if (r?.id) allRecordings.push(r);
  }
}
console.log('Flattened ' + pages.length + ' Grain page(s) into ' + allRecordings.length + ' recordings.');
return [{ json: { recordings: allRecordings, page_count: pages.length } }];

const batchPageId = $('Create Batch Page').first().json.id;
const blocks = $input.first().json?.results || [];

// Look for a child_database named "Content Lineup" (or legacy "Post Lineup")
const postLineupDb = blocks.find(b => {
  if (b.type !== 'child_database') return false;
  const title = (b.child_database?.title || '').toLowerCase();
  return title.includes('content lineup') || title.includes('post lineup');
});

return [{
  json: {
    id: postLineupDb ? postLineupDb.id : null,
    found: !!postLineupDb,
    batch_page_id: batchPageId
  }
}];

const blocks = $input.first().json?.results || [];
const resources = blocks.find(b => b.type === 'child_page' && (b.child_page?.title || '').toLowerCase().includes('resources'));
if (!resources) {
  throw new Error('Could not find a "Resources" child_page inside the navigation callout. Blocks: ' +
    blocks.map(b => `${b.type}: "${b.child_database?.title || b.child_page?.title || '(no title)'}" [${b.id}]`).join(' | '));
}
return [{ json: { id: resources.id, found: true } }];

const blocks = $input.first().json?.results || [];

// Prefer column_list (the General Pages callout lives inside its columns).
// If a callout exists at the top level (older structure), pass it straight through with a flag.
const columnList = blocks.find(b => b.type === 'column_list');
if (columnList) {
  return [{ json: { id: columnList.id, kind: 'column_list' } }];
}

const topCallout = blocks.find(b => b.type === 'callout');
if (topCallout) {
  return [{ json: { id: topCallout.id, kind: 'callout_direct' } }];
}

throw new Error('Could not find a column_list or callout inside the Resources page. Blocks: ' +
  blocks.map(b => `${b.type} [${b.id}]`).join(' | '));

// Input: result of fetching the Resources page's column_list children (i.e. the column blocks),
// OR a passthrough if the Resources page had a direct callout (no column_list).
const ref = $('Find Resources Column List or Callout').first().json;

if (ref.kind === 'callout_direct') {
  // The "callout" branch — emit a single item carrying the callout ID so the next step fetches it.
  return [{ json: { id: ref.id, _is_callout: true } }];
}

const cols = ($input.first().json?.results || []).filter(b => b.type === 'column');
if (cols.length === 0) {
  throw new Error('column_list inside Resources had no column children.');
}
return cols.map(c => ({ json: { id: c.id, _is_callout: false } }));

// Aggregate every column's children and find the callout whose title text matches "General Pages".
// Resources can have multiple callouts (Brand Suite, General Pages, Bespoke Pages…) — pick by name.
const splitItems = $('Split Resources Columns').all();
if (splitItems.length === 1 && splitItems[0].json?._is_callout) {
  return [{ json: { id: splitItems[0].json.id, source: 'direct' } }];
}

function calloutText(b) {
  if (b.type !== 'callout') return '';
  const rt = b.callout?.rich_text || [];
  return rt.map(t => t?.plain_text || t?.text?.content || '').join('').trim();
}

const allChildren = $input.all();
const seenCallouts = [];

// First pass — exact title match for "General Pages"
for (const item of allChildren) {
  const blocks = item.json?.results || [];
  for (const b of blocks) {
    if (b.type !== 'callout') continue;
    const title = calloutText(b);
    seenCallouts.push({ id: b.id, title });
    if (title.toLowerCase().includes('general pages')) {
      return [{ json: { id: b.id, source: 'column', matched_title: title } }];
    }
  }
}

throw new Error('Could not find a callout titled "General Pages" inside Resources columns. Saw callouts: ' +
  JSON.stringify(seenCallouts));

// Sort all batches by parsed Batch N descending and pick the highest.
// This runs before the current batch has been created, so the highest is the previous batch.
const results = $input.first().json?.results || [];

function parseBatchNum(page) {
  const props = page.properties || {};
  const titleProp = Object.values(props).find(p => p && p.type === 'title');
  const title = titleProp?.title?.[0]?.plain_text || '';
  const m = title.match(/Batch\s+(\d+)/i);
  return { num: m ? parseInt(m[1], 10) : 0, title };
}

const sorted = results
  .map(p => ({ ...parseBatchNum(p), id: p.id }))
  .filter(p => p.num > 0)
  .sort((a, b) => b.num - a.num);

if (sorted.length === 0) {
  console.log('No prior batches found — this is the first batch.');
  return [{ json: { has_previous: false, previous_batch_page_id: 'NO_PREVIOUS', previous_batch_number: 0, previous_batch_title: '' } }];
}

const prev = sorted[0];
console.log(`Previous batch: "${prev.title}" (id=${prev.id})`);
return [{ json: { has_previous: true, previous_batch_page_id: prev.id, previous_batch_number: prev.num, previous_batch_title: prev.title } }];

const prevMeta = $('Find Previous Batch').first().json;
if (!prevMeta.has_previous) {
  return [{ json: { has_previous: false, has_db: false, db_id: '', previous_batch_number: 0, previous_batch_title: '' } }];
}

const blocks = $input.first().json?.results || [];
const db = blocks.find(b =>
  b.type === 'child_database' &&
  /content lineup|post lineup/i.test(b.child_database?.title || '')
);
if (!db) {
  console.log('Previous batch page had no Content Lineup child_database. Blocks: ' +
    blocks.map(b => `${b.type}: "${b.child_database?.title || b.child_page?.title || '?'}"`).join(' | '));
  return [{ json: { has_previous: true, has_db: false, db_id: 'NO_DB', previous_batch_number: prevMeta.previous_batch_number, previous_batch_title: prevMeta.previous_batch_title } }];
}

return [{ json: { has_previous: true, has_db: true, db_id: db.id, previous_batch_number: prevMeta.previous_batch_number, previous_batch_title: prevMeta.previous_batch_title } }];

// Preserve the full workflow context from upstream — earlier versions returned only the
// previous-batch fields, dropping fallback_candidates and everything else that downstream
// nodes (Pick Fallback Call, Prepare Mine Ideas Context) rely on.
const upstream = $('Extract Transcript Text').first().json || {};

const prevMeta = $('Find Previous Content Lineup DB').first().json;
const queryResult = $input.first().json;

function emit(extra) {
  return [{ json: { ...upstream, ...extra } }];
}

if (!prevMeta.has_previous || !prevMeta.has_db) {
  const reason = !prevMeta.has_previous ? '(first batch — no previous batch to reference)' : '(previous batch had no Content Lineup database)';
  return emit({
    previous_batch_block: `PREVIOUS BATCH IDEAS: None ${reason}`,
    previous_batch_number: prevMeta.previous_batch_number || 0,
    previous_batch_idea_count: 0
  });
}

const rows = queryResult?.results || [];
function plain(rich) { return (rich || []).map(t => t?.plain_text || '').join(''); }
function getProp(props, name) {
  const p = props?.[name];
  if (!p) return '';
  if (p.type === 'title')     return plain(p.title);
  if (p.type === 'rich_text') return plain(p.rich_text);
  if (p.type === 'select')    return p.select?.name || '';
  if (p.type === 'status')    return p.status?.name || '';
  if (p.type === 'multi_select') return (p.multi_select || []).map(o => o.name).join(', ');
  return '';
}

const ideas = rows.map(r => ({
  idea:           getProp(r.properties, 'Idea'),
  status:         getProp(r.properties, 'Status') || getProp(r.properties, 'Review Status'),
  content_pillar: getProp(r.properties, 'Content Pillar'),
  topic:          getProp(r.properties, 'Topic'),
  format:         getProp(r.properties, 'Format')
})).filter(i => i.idea);

const TERMINAL = new Set(['approved', 'scheduled', 'posted', 'scratch']);
const filtered = ideas.filter(i => TERMINAL.has((i.status || '').trim().toLowerCase()));
console.log(`Previous batch has ${ideas.length} idea(s); ${filtered.length} terminal status.`);

if (filtered.length === 0) {
  return emit({
    previous_batch_block: `PREVIOUS BATCH IDEAS (Batch ${prevMeta.previous_batch_number}): No terminal-status ideas yet (all ${ideas.length} ideas are still For Review / Needs Improvement). No prior-batch constraint applies — mine freely.`,
    previous_batch_number: prevMeta.previous_batch_number,
    previous_batch_idea_count: 0
  });
}

const lines = filtered.map((i, idx) => {
  const status = i.status || '(no status)';
  const pillar = i.content_pillar ? ` | pillar: ${i.content_pillar}` : '';
  const topic  = i.topic ? ` | topic: ${i.topic}` : '';
  return `${idx + 1}. [${status}] ${i.idea}${pillar}${topic}`;
}).join('\n');

const block = `PREVIOUS BATCH IDEAS (Batch ${prevMeta.previous_batch_number} - "${prevMeta.previous_batch_title}"):\nThe following ideas have a TERMINAL status. Apply PREVIOUS BATCH AWARENESS rules from the system prompt: avoid near-duplicates of Approved/Scheduled/Posted; avoid repeating angles that were Scratched.\n\n${lines}`;
return emit({
  previous_batch_block: block,
  previous_batch_number: prevMeta.previous_batch_number,
  previous_batch_idea_count: filtered.length
});

// Submission Status Gate
// Only let the workflow run when the Notion row's Status is the "fresh" state.
// The Ideation Launcher DB has these options: pending, processing, done, failed.
// New form submissions arrive with Status = pending (or sometimes null if not defaulted).
// Anything else means another execution has already taken this row — skip silently.

const item = $input.first().json;
const rawStatus = item.Status ?? item.status ?? null;
const statusText = (typeof rawStatus === 'string')
  ? rawStatus.trim().toLowerCase()
  : (rawStatus?.name?.toLowerCase?.() || '');

const allowed = ['', 'pending', 'new'];
const isFresh = allowed.includes(statusText);

if (!isFresh) {
  console.log(`Submission ${item.id} skipped — Status="${rawStatus}" (gate only accepts empty / pending).`);
  return [];
}

console.log(`Submission ${item.id} accepted (Status="${rawStatus ?? 'null'}").`);
return [{ json: item }];

// Normalize Notion Webhook Payload
// n8n's Webhook trigger wraps the incoming request as { headers, query, body }.
// Notion's "Send webhook" automation puts the page object at body.data.

const wrapper = $input.first().json || {};
const body = wrapper.body || wrapper;
const page = body.data || body.page || body;
const props = page.properties || {};

function plain(rich) {
  return (rich || []).map(t => t?.plain_text || t?.text?.content || '').join('');
}

function readProp(p) {
  if (!p) return null;
  switch (p.type) {
    case 'title':            return plain(p.title);
    case 'rich_text':        return plain(p.rich_text);
    case 'select':           return p.select?.name ?? null;
    case 'status':           return p.status?.name ?? null;
    case 'multi_select':     return (p.multi_select || []).map(o => o.name);
    case 'date':             return p.date ?? null;
    case 'checkbox':         return !!p.checkbox;
    case 'number':           return p.number ?? null;
    case 'people':           return (p.people || []).map(per => per.person?.email || per.name || per.id);
    case 'email':            return p.email ?? null;
    case 'phone_number':     return p.phone_number ?? null;
    case 'url':              return p.url ?? null;
    case 'created_time':     return p.created_time ?? null;
    case 'last_edited_time': return p.last_edited_time ?? null;
    case 'formula':          return p.formula?.string ?? p.formula?.number ?? p.formula?.boolean ?? null;
    default: return null;
  }
}

if (!page.id) {
  throw new Error('Webhook payload missing page id. Top-level keys: ' + Object.keys(wrapper).join(', ') +
                  '; body keys: ' + (body && typeof body === 'object' ? Object.keys(body).join(', ') : '(none)'));
}

const flat = { id: page.id };
for (const [key, prop] of Object.entries(props)) {
  flat[key] = readProp(prop);
}

console.log(`Normalized submission ${flat.id} — keys: ${Object.keys(flat).join(', ')}`);
return [{ json: flat }];

// Build a Google Docs batchUpdate that deletes the placeholder and inserts the freshly fetched transcript.
const previous = $('Extract Transcript Text').first().json;
const refetchResp = $input.first().json;

const fetchFailed = !!refetchResp?.error || !!refetchResp?.code;
const newTranscriptText = fetchFailed ? '' : (refetchResp?.data || '').trim();

if (!newTranscriptText) {
  throw new Error('Re-fetch from Grain returned no transcript text. The recording may not yet have a transcript available, or the Grain ID is invalid. Recording ID: ' + (previous.latest_grain_call_id || '(unknown)') + '.');
}

const docId = previous.transcript_doc_id;
if (!docId) {
  throw new Error('Cannot overwrite doc: no doc_id available. transcript_doc_url=' + (previous.transcript_doc_url || '(none)'));
}

const endIndex = previous.transcript_doc_end_index || 1;
const requests = [];
// Delete existing content (1 to endIndex-1 — leave the trailing newline that Google requires).
if (endIndex > 2) {
  requests.push({ deleteContentRange: { range: { startIndex: 1, endIndex: endIndex - 1 } } });
}
requests.push({ insertText: { location: { index: 1 }, text: newTranscriptText } });

console.log(`Overwriting doc ${docId}: delete [1, ${endIndex - 1}), insert ${newTranscriptText.length} chars.`);
return [{
  json: {
    ...previous,
    transcript_text: newTranscriptText,
    overwrite_doc_id: docId,
    overwrite_body: { requests }
  }
}];

// After the doc has been overwritten, package the data in the same shape that
// Extract Transcript Text would have emitted on the happy path. This lets the
// downstream Query Format Bank Pass 1 (and all references to Extract Transcript Text)
// work without knowing we took the recovery branch.
const prev = $('Build Doc Overwrite Body').first().json;
console.log(`Refreshed transcript ready: ${(prev.transcript_text || '').length} chars.`);
return [{
  json: {
    ...prev,
    transcript_text: prev.transcript_text,
    transcript_is_placeholder: false,
    recovered_from_placeholder: true
  }
}];

const ctx = $('Parse Final Ideas').first().json;
const hookBankResult = $input.first().json;

function plain(rich) {
  return (rich || []).map(t => t?.plain_text || '').join('').trim();
}
function readProp(p) {
  if (!p) return '';
  if (p.type === 'title')        return plain(p.title);
  if (p.type === 'rich_text')    return plain(p.rich_text);
  if (p.type === 'select')       return p.select?.name || '';
  if (p.type === 'multi_select') return (p.multi_select || []).map(o => o.name).join(', ');
  if (p.type === 'url')          return p.url || '';
  return '';
}

// Hook Bank may come paginated as multiple input items — flatten all results
const hookBankPages = $input.all().flatMap(it => (it.json && it.json.results) || []);
const hookTemplates = hookBankPages.map(page => {
  const p = page.properties || {};
  let templateName = '';
  for (const [, prop] of Object.entries(p)) {
    if (prop?.type === 'title') { templateName = plain(prop.title); if (templateName) break; }
  }
  // Format is a RELATION → array of format page IDs
  const formatRelation = (p['Format']?.relation || []).map(r => r.id);
  return {
    name: templateName,
    why_it_works: readProp(p['Why It Works']) || readProp(p['Why it works']) || readProp(p['Why']),
    format_ids: formatRelation,
    example: readProp(p['Example']),
  };
}).filter(h => h.name);
console.log('Hook Bank loaded:', hookTemplates.length, 'templates total | with format relation:', hookTemplates.filter(h => h.format_ids.length > 0).length, '| universal (no format):', hookTemplates.filter(h => h.format_ids.length === 0).length);

const ideas = ctx.final_ideas || [];

// Excerpt the intel brief so the hook writer can match the client's voice (especially for parentheticals).
