function rt(arr) { return ((arr || []).map(t => t.plain_text || (t.text && t.text.content) || '')).join(''); }

function serializeBlocks(blocks, depth) {
  const indent = '  '.repeat(depth || 0);
  const out = [];
  for (const b of (blocks || [])) {
    const t = b.type;
    const d = b[t] || {};
    let line = '';
    switch (t) {
      case 'heading_1': line = '\n# ' + rt(d.rich_text); break;
      case 'heading_2': line = '\n## ' + rt(d.rich_text); break;
      case 'heading_3': line = '\n### ' + rt(d.rich_text); break;
      case 'paragraph': line = rt(d.rich_text); break;
      case 'bulleted_list_item': line = indent + '- ' + rt(d.rich_text); break;
      case 'numbered_list_item': line = indent + '1. ' + rt(d.rich_text); break;
      case 'to_do': line = indent + (d.checked ? '- [x] ' : '- [ ] ') + rt(d.rich_text); break;
      case 'quote': line = '> ' + rt(d.rich_text).replace(/\n/g, '\n> '); break;
      case 'callout': line = '[!callout] ' + rt(d.rich_text); break;
      case 'toggle': line = '▸ ' + rt(d.rich_text); break;
      case 'code': line = '```' + (d.language || '') + '\n' + rt(d.rich_text) + '\n```'; break;
      case 'divider': line = '---'; break;
      case 'table': line = ''; break;
      case 'table_row': {
        const cells = (d.cells || []).map(c => rt(c).replace(/\|/g, '\\|'));
        line = '| ' + cells.join(' | ') + ' |';
        break;
      }
      case 'column_list':
      case 'column':
      case 'synced_block':
        line = '';
        break;
      case 'child_page': line = '(child page: ' + (d.title || '') + ')'; break;
      case 'child_database': line = '(child database: ' + (d.title || '') + ')'; break;
      default:
        if (Array.isArray(d.rich_text) && d.rich_text.length) line = rt(d.rich_text);
        else line = '';
    }
    if (line) out.push(line);
    // descend one level via l2Map (we don't fetch L3, but l2_map only fills for direct top-level children)
    if (b.has_children) {
      const kids = l2Map[b.id] || [];
      const nextDepth = (t === 'bulleted_list_item' || t === 'numbered_list_item' || t === 'to_do' || t === 'toggle') ? (depth || 0) + 1 : (depth || 0);
      const childText = serializeBlocks(kids, nextDepth);
      if (childText) out.push(childText);
    }
  }
  return out.join('\n');
}

