function classifyLength(desc, name) {
  const d = (desc || '').toLowerCase();
  const n = (name || '').toLowerCase();
  if (/1,?000\+\s*characters|1k\+\s*characters|1,?000 ?\+ char/i.test(d)) return 'long';
  if (/280[\s\-]+1,?000\s*characters|280[\s\-]+1k/i.test(d)) return 'medium';
  if (/under\s*280|equal to or under 280|≤\s*280|<\s*280|under 280 char/i.test(d)) return 'short';
  if (n.includes('long form') || n.includes('long-form')) return 'long';
  if (n.includes('medium form')) return 'medium';
  if (n.includes('short form')) return 'short';
  if (n.includes('one-liner') || n.includes('one liner') || n === 'the one-liner') return 'short';
  if (n.includes('block text')) return 'short';
  if (n.includes('full expanded listicle')) return 'long';
  if (n.includes('high-volume bulleted')) return 'medium';
  if (n.includes('step-by-step short')) return 'short';
  if (n.includes('contrast/comparison listicle')) return 'medium';
  if (n.includes('binary contrast')) return 'short';
  if (n.includes('carousel')) return 'long';
  if (n.includes('article ')) return 'long';
  if (n.includes('summary of a podcast')) return 'long';
  if (n.includes('breakdown')) return 'long';
  if (n.includes('personal story')) return 'long';
  if (n.includes('how-to guide')) return 'long';
  if (n.includes('contrarian belief') || n.includes('hot take')) return 'medium';
  if (n.includes('client transformation')) return 'long';
  if (n.includes('framework/formula')) return 'long';
  if (n.includes('hiring post')) return 'long';
  if (n.includes('linkedin re-intro')) return 'long';
  if (n.includes('lead magnet')) return 'medium';
  if (n.includes('horizontal') || n.includes('video clip')) return 'short';
  if (n.includes('embedded full video')) return 'short';
  if (n.includes('one-liner + clip')) return 'short';
  if (n.includes('visual + short caption') || n.includes('infographic')) return 'medium';
  if (n.includes('quote retweet') || n.includes('qrt')) return 'medium';
  if (n.includes('opinion') || n.includes('observation') || n.includes('pov') || n.includes('questions')) return 'medium';
  if (n.includes('update (building in public)')) return 'medium';
  if (n.includes('meme') || n.includes('announcement')) return 'medium';
  if (n.includes('scientific study')) return 'medium';
  if (n.includes('borrowed credibility')) return 'long';
  if (n.includes('resources')) return 'medium';
  return 'medium';
}

