function extractJSON(raw) {
  try { return JSON.parse((raw || '').replace(/^```(json)?/i,'').replace(/```$/,'').trim()); } catch (e) {}
  const openers = ['{', '['];
  const closers = { '{': '}', '[': ']' };
  for (let start = 0; start < raw.length; start++) {
    if (!openers.includes(raw[start])) continue;
    const open = raw[start], close = closers[open];
    let depth = 0, inStr = false, esc = false;
    for (let i = start; i < raw.length; i++) {
      const c = raw[i];
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (c === open) depth++;
      else if (c === close) {
        depth--;
        if (depth === 0) {
          try { return JSON.parse(raw.slice(start, i + 1)); } catch (e2) { break; }
        }
      }
    }
  }
  return null;
}

