const initialBuckets = {
  'shared-long': t_shared_long,
  'shared-short': t_shared_short,
  'li_only-long': t_li_long,
  'li_only-short': t_li_short,
  'x_only-long': t_x_long,
  'x_only-short': t_x_short,
};
const buckets = { ...initialBuckets };
let bufferRemaining = buffer_target;
const formatTally = {};
const flags = [];

function platformPrefix(p) {
  if (p === 'LinkedIn & X/Twitter') return 'shared';
  if (p === 'LinkedIn') return 'li_only';
  if (p === 'X/Twitter' || p === 'X' || p === 'Twitter') return 'x_only';
  return null;
}
function bucketOf(platform, format) {
  const pp = platformPrefix(platform);
  if (!pp) return null;
  const fmt = bankByName[format];
  const rawLen = (fmt && fmt.length) || 'medium';
  const len = (rawLen === 'short') ? 'short' : 'long';
  return pp + '-' + len;
}
function deficit(bucket) { return buckets[bucket] || 0; }
function maxDeficit() { return Math.max(0, ...Object.values(buckets)); }

// Score a candidate for an idea given current state.
// Higher = better. Negative = invalid.
const HARD_CAP = 3;
function score(c) {
  if (!c || !c.format) return -100;
  const ft = formatTally[c.format] || 0;
  if (ft >= HARD_CAP) return -50;
  const b = bucketOf(c.platform, c.format);
  if (!b) return 0;
  const d = deficit(b);
  if (d > 0) return 100 + d * 10 - ft * 5; // strongly prefer filling deficits
  if (bufferRemaining > 0) return 30 - ft * 5; // can take buffer slot
  return -5; // no room
}

