});

// Sort ideas by "constrained-first": ideas with fewer valid candidates pick first
function validCount(entry) {
  return entry.candidates.filter(c => {
    const ft = formatTally[c.format] || 0;
    return ft < HARD_CAP;
  }).length;
}

// Multi-pass allocation
let safety = 200;
while (safety-- > 0) {
  // Pick the unassigned idea with the fewest valid options
  const unassigned = ideas.filter(e => !e.assigned);
  if (unassigned.length === 0) break;
  unassigned.sort((a, b) => validCount(a) - validCount(b));

  let madeProgress = false;
  for (const entry of unassigned) {
    // Find best candidate by score
    let bestIdx = -1, bestScore = -Infinity;
    for (let i = 0; i < entry.candidates.length; i++) {
      const s = score(entry.candidates[i]);
      if (s > bestScore) { bestScore = s; bestIdx = i; }
    }
    if (bestIdx < 0 || bestScore < 0) {
      // No valid placement right now — skip and hope state changes (won't, but safety loop handles it)
      continue;
    }
    const c = entry.candidates[bestIdx];
    const b = bucketOf(c.platform, c.format);
    if (b && buckets[b] > 0) buckets[b]--;
    else if (bufferRemaining > 0) bufferRemaining--;
    formatTally[c.format] = (formatTally[c.format] || 0) + 1;
    entry.assigned = {
      format: c.format,
      platform: c.platform,
      length: bankByName[c.format]?.length || 'medium',
      rank: bestIdx + 1,
      brief: bestIdx === 0 ? entry.idea.format_brief : '',
    };
    madeProgress = true;
    if (entry.candidates.indexOf(c) > 0 && b && deficit(b) >= 0) {
      // Used a fallback rank — fine, no flag needed
    }
  }
  if (!madeProgress) break;
}

// Last-ditch: anything still unassigned takes rank-1 (overflow flagged)
