  if (entry.assigned) continue;
  const c = entry.candidates[0];
  if (!c) continue;
  entry.assigned = {
    format: c.format,
    platform: c.platform,
    length: bankByName[c.format]?.length || 'medium',
    rank: 1,
    brief: entry.idea.format_brief,
  };
  formatTally[c.format] = (formatTally[c.format] || 0) + 1;
  flags.push('Idea "' + entry.idea.topic + '" forced into overflow (no bucket fit, soft caps relaxed). Format tally: ' + JSON.stringify(formatTally));
}

