const platformDist = finalIdeas.reduce((acc, i) => { acc[i.platform] = (acc[i.platform]||0)+1; return acc; }, {});
const lengthDist = finalIdeas.reduce((acc, i) => { acc[i.format_length] = (acc[i.format_length]||0)+1; return acc; }, {});

